// This JavaScript code dynamically changes the sorting order and visibility based on clicked options.
document.addEventListener("DOMContentLoaded", function () {
    const toggleOptions = document.querySelectorAll('input[type="checkbox"]');

    // Set default sort order
    const defaultSortOrder = ['problem', 'solution', 'note'];
    let currentSortOrder = [...defaultSortOrder];

    // Find all the elements that need to be sorted or toggled
    const notesContainer = document.getElementById('note-container');
    const problemElement = document.querySelector('#problem');
    const solutionElement = document.querySelector('#solution');
    const noteElements = Array.from(notesContainer.getElementsByClassName('note'));

    toggleOptions.forEach(option => {
        option.addEventListener('change', function () {
            if (option.checked) {
                currentSortOrder.push(option.value);
            } else {
                currentSortOrder = currentSortOrder.filter(item => item !== option.value);
            }
        });
    });

    // Initially show the note with the highest priority
    const firstNote = noteElements[0]; // First element (by default)
    if (!firstNote.classList.contains('hidden')) {
        firstNote.classList.add('hidden');
    }

    // Display details for each note based on their sort order
    noteElements.forEach(note => {
        const titleText = note.getAttribute('title');
        const data = JSON.parse(note.getAttribute('data'));

        const remainingNotes = noteElements.slice(1); // All other notes

        let displayText;

        if (currentSortOrder.includes('problem')) {
            displayText = `${titleText} (Problem): ${data.problem}`;
        } else if (currentSortOrder.includes('solution')) {
            displayText = `${titleText} (Solution): ${data.solution}`;
        } else if (currentSortOrder.includes('note')) {
            displayText = `${titleText}: ${data.note}`;
        } else {
            displayText = titleText; // If no sections are requested, just display the title
        }

        note.innerHTML = `
            <div style="max-width: 600px;">${displayText}</div>
        `;

        // Show/hide the note based on its position in the list
        if (noteElements.indexOf(note) === 0) {
            note.classList.remove('hidden');
        } else {
            note.classList.add('hidden');
        }
    });
});
