func CubeTower(spacedCount int) [][]string {
	tower := make([][]string, spacedCount)
	for i := 0; i < spacedCount; i++ {
		level := make([]string, spacedCount-i)
		for j := 0; j < level.length(); j++ {
			level[j] = fmt.Sprintf("%d ", (spacedCount-i)*7 - j)
